CREATE TABLE IF NOT EXISTS "quote_counters" ("workspace_id" uuid PRIMARY KEY REFERENCES "workspaces"("id") ON DELETE CASCADE, "next_number" bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "quotes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE CASCADE, "number" varchar(40) NOT NULL, "customer_name" varchar(120) NOT NULL, "customer_email" varchar(254) NOT NULL DEFAULT '', "customer_company" varchar(120) NOT NULL DEFAULT '', "issue_date" date NOT NULL, "valid_until" date NOT NULL, "description" varchar(500) NOT NULL, "quantity" numeric(12,3) NOT NULL CHECK ("quantity" > 0), "unit_price_minor" bigint NOT NULL CHECK ("unit_price_minor" >= 0), "currency" char(3) NOT NULL, "status" varchar(24) NOT NULL DEFAULT 'Draft' CHECK ("status" IN ('Draft','Sent','Accepted','Declined','Converted')), "converted_invoice_id" uuid, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE ("workspace_id","number"));
CREATE INDEX IF NOT EXISTS "quotes_workspace_created_idx" ON "quotes"("workspace_id","created_at");
